class Framework {
  run(app: App) {
    app.onStart();
  }
}
class App {
  onStart() {
    // application startup logic
  }
}
new Framework().run(new App());

interface Plugin { onEvent(e: any): void }
class Framework {
  plugins: Plugin[] = [];
  register(p: Plugin) { this.plugins.push(p) }
  trigger(e: any) { this.plugins.forEach(p => p.onEvent(e)) }
}
class SlowPlugin implements Plugin {
  onEvent(e: any) { while(true) {} }
}

// Version A: application orchestrates framework services
class AppA {
  constructor(private svc: Service) {}
  start() { this.svc.doWork(); }
}
new AppA(new Service()).start();

// Version B: framework manages flow and calls app hooks
interface AppB { onStart(): void }
class Framework {
  run(app: AppB) { app.onStart(); }
}
class MyApp implements AppB { onStart() { /* startup */ } }
new Framework().run(new MyApp());
